class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        if x == 0:
            return 0

        digit_sum = 0
        temp_x = x
        while temp_x > 0:
            digit_sum += temp_x % 10
            temp_x //= 10

        if x % digit_sum == 0:
            return digit_sum
        else:
            return -1
```

