class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        if not nums:
            return 0

        max_len = 1
        n = len(nums)

        # Check strictly increasing subarrays
        current_len = 1
        for i in range(1, n):
            if nums[i] > nums[i-1]:
                current_len += 1
            else:
                max_len = max(max_len, current_len)
                current_len = 1

        # Check strictly decreasing subarrays
        current_len = 1
        for i in range(1, n):
            if nums[i] < nums[i-1]:
                current_len += 1
            else:
                max_len = max(max_len, current_len)
                current_len = 1

        return max_len
```

