class Solution:
    def isValid(self, word: str) -> bool:
        # Check minimum length
        if len(word) < 3:
            return False

        # Check if only digits and English letters
        for char in word:
            if not (char.isdigit() or char.isalpha()):
                return False

        # Check if has at least one vowel
        vowels = set('aeiouAEIOU')
        if not any(v in word for v in vowels):
            return False

        # Check if has at least one consonant
        consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')
        if not any(c in consonants for c in word):
            return False

        return True
```

