class Solution:
    def clearDigits(self, s: str) -> str:
        stack = []
        for char in s:
            if char.isdigit():
                # Find the closest non-digit character to the left
                left_char = None
                for i in range(len(stack)):
                    if stack[i].isdigit():
                        left_char = stack[i]
                        break
                if left_char is not None:
                    # Remove both the digit and the left non-digit
                    stack.pop()  # Remove digit
                    stack.pop()  # Remove left non-digit
                else:
                    # No non-digit to the left, just remove the digit
                    stack.pop()
            else:
                # Non-digit, push to stack
                stack.append(char)

        return ''.join(stack)
