        # Create a mapping of each character to its position in the string
        pos = {char: i for i, char in enumerate(s)}

        # For each character in s, find the k-th character after it
        result = []
        for char in s:
            # Find the index of the character
            idx = pos[char]
            # Calculate the new index (k steps forward)
            new_idx = (idx + k) % len(s)
            # Add the character at the new position
            result.append(s[new_idx])

