class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0

        # Iterate over all starting positions
        for i in range(n):
            # For each starting position, iterate over all ending positions
            for j in range(i, n):
                # Count 0's and 1's in s[i:j+1]
                count0 = 0
                count1 = 0
                for char in s[i:j+1]:
                    if char == '0':
                        count0 += 1
                    else:
                        count1 += 1

                # Check if substring satisfies k-constraint
                if count0 <= k or count1 <= k:
                    count += 1

        return count
