class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        # Find all primes up to sqrt(r)
        limit = int(r**0.5)
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False

        for i in range(2, limit + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False

        # Count special numbers (perfect squares of primes)
        special_count = 0
        for p in range(2, limit + 1):
            if is_prime[p]:
                if p * p >= l and p * p <= r:
                    special_count += 1

        # Total numbers in range minus special numbers
        return (r - l + 1) - special_count
