class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        results = []

        for i in range(n - k + 1):
            subarray = nums[i:i+k]

            # Check if subarray is sorted
            is_sorted = True
            for j in range(1, len(subarray)):
                if subarray[j] < subarray[j-1]:
                    is_sorted = False
                    break

            # Check if subarray is consecutive
            is_consecutive = True
            for j in range(1, len(subarray)):
                if subarray[j] - subarray[j-1] != 1:
                    is_consecutive = False
                    break

            # If not sorted or not consecutive, power is -1
            if not is_sorted or not is_consecutive:
                results.append(-1)
            else:
                # Power is the maximum element
                results.append(max(subarray))

        return results
