class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def lcm(a, b):
            return abs(a * b) // gcd(a, b)

        def calculate_gcd_and_lcm(nums):
            if not nums:
                return 0, 0
            g = nums[0]
            for x in nums[1:]:
                g = gcd(g, x)
            l = 1
            for x in nums:
                l = lcm(l, x)
            return g, l

        # Calculate GCD and LCM of the original array
        g_all, l_all = calculate_gcd_and_lcm(nums)
        current_score = l_all * g_all

        # Try removing each element
        max_score = current_score

        for i in range(len(nums)):
            # Remove element at index i
            nums_without_i = nums[:i] + nums[i+1:]
            g_i, l_i = calculate_gcd_and_lcm(nums_without_i)
            current_score_i = l_i * g_i
            max_score = max(max_score, current_score_i)

        return max_score
